    );
    let api = read_plan_for_copy(&alias, &db, &root, &s_pin(&pins));
    println!(
        "P1 read_plan_for_copy(DEST/{LONG_S_SHM}): {:?}",
        api.as_ref().map(|p| p.bytes().len()).map_err(|e| e.to_string())
    );
    let before_db = std::fs::read(&db).unwrap();
    let a = alias.to_str().unwrap();
