164	/// Validate plan custody against both SQLite families before any database opens.
165	/// An absent destination root must have an existing parent, as creation requires.
166	/// This protects owner-selected paths under the same trusted-filesystem contract
167	/// as archive creation; it does not fence concurrent hostile path replacement.
168	pub fn read_plan_for_copy(
169	    path: &Path,
170	    source: &Path,
171	    destination_root: &Path,
172	    expected_archive: &[u8; 32],
173	) -> Result<Plan> {
174	    let source = std::fs::canonicalize(source)?;
175	    plan_outside_sqlite(&source, path)?;
176	    let root = if destination_root.exists() {
177	        std::fs::canonicalize(destination_root)?
178	    } else {
179	        std::fs::canonicalize(parent_directory(destination_root))?.join(
180	            destination_root
181	                .file_name()
182	                .ok_or(Error::Invalid("destination directory"))?,
